  SchoolConfig_1_Tips = {
    Text = "·Cảm ứng chìa khóa bạc: Vào cuối lượt, nhận được 250 điểm năng lượng chìa khóa bạc. Sau khi sử dụng mật lệnh, tất cả các thể thức tỉnh nhận được 5 điểm điên cuồng. Khi phát động mật lệnh lần thứ hai, thay đổi thành phát động \"Bình minh chưa bị lãng quên\": Chọn 1 mật lệnh đã mở khóa để phát động và làm cho nó có hiệu lực 2 lần, mỗi mật lệnh đã mở khóa chỉ có thể chọn 1 lần trong cuộc thám hiểm này, không thể chọn mật lệnh mang theo ban đầu. \n·Vạn Tượng Sáng Tạo: Nếu Người Giữ Gìn đạt cấp độ 45, vào đầu cuộc thám hiểm phát hiện 1 di vật bạc. \n·Kỹ năng hỗn loạn: Với mỗi 1 điểm sự thông thạo giới vực trong đội, sau khi sử dụng mật lệnh, tất cả các thể thức tỉnh sẽ nhận thêm 0.05 điểm điên cuồng. \n·Sống trong cái chết: Trong bất kỳ đội nào, nếu có thân thể hỗn độn, kháng cự tử vong +100%. \n·Cộng sinh hỗn độn: Khi phối hợp với các giới vực khác,\"Cảm ứng chìa khóa bạc\",\"Vạn Tượng Sáng Tạo\",\"Kỹ năng hỗn loạn\" sẽ không còn có hiệu lực, luôn kích hoạt hiệu ứng tài năng thuần khiết của các giới vực khác, và nhận được các hiệu ứng cộng sinh khác nhau tùy theo từng giới vực. \n·Cộng sinh hải vực: Trong đội, với mỗi 1 thân thể hỗn độn, sát thương xúc tu cơ bản tăng 1% sinh lực tối đa. Sau khi thân thể hỗn độn phát động bùng nổ điên loạn, vào cuối lượt sẽ điều khiển thêm 1 xúc tu tấn công kẻ thù, và làm cho tất cả các thể thức tỉnh sâu thẳm nhận được 10 điểm điên cuồng. \n·Dung hợp Phôi thai: Thân thể hỗn độn sau khi sử dụng bùng nổ điên loạn sẽ tăng cường dung hợp phôi thai +35. \n·Cộng sinh siêu chiều: Khi bắt đầu trận đấu, trong đội với mỗi 1 thân thể hỗn độn, tăng vĩnh viễn 1% sức mạnh sinh lực tối đa và giảm 0.5% sức mạnh sinh lực tối đa của tất cả kẻ thù, đồng thời làm cho tất cả các thể thức tỉnh siêu chiều tăng sát thương chí mạng 10%."
  },
  SchoolConfig_2_Name = {
