  SchoolConfig_2_SchoolBattleTips_1 = {
    Text = "·Dung hợp Phôi thai: Khi bắt đầu lượt, Dung hợp Phôi thai+<BlueQuality:[Arg1]>.\n·Lò nung đỏ thẫm: Khi bắt đầu lượt, tích lũy <BlueQuality:[Arg9]> điểm Lò nung đỏ thẫm. Sau khi chiến đấu kết thúc, tích lũy <BlueQuality:[Arg2]> điểm Lò nung đỏ thẫm, nếu Cõi hiện tại là \"Thịt máu thuần khiết\" lượng tích lũy nhân đôi, tối đa tích lũy <BlueQuality:[Arg3]> điểm. Khi chiến đấu kết thúc, mỗi \"Phôi thai\" còn lại trong tay bài, tích lũy thêm <BlueQuality:[Arg2]> điểm Lò nung đỏ thẫm.\n·Hấp thụ Phôi thai: Bùng nổ điên loạn của Thân thể được đánh thức thịt máu sẽ tiêu thụ \"Phôi thai\" và kích hoạt hiệu ứng Nuốt chửng. Sau lần đầu tiên trong mỗi lượt đội kích hoạt \"Nuốt chửng\", nhận lá chắn bằng <BlueQuality:[Arg4]>% Sinh lực tối đa( <BlueQuality:[Arg5]> ) và Sức mạnh tạm thởi bằng <BlueQuality:[Arg6]>% Sinh lực tối đa( <BlueQuality:[Arg7]> )."
