  SchoolConfig_3_SchoolBattleTips_1 = {
    Text = "·Xuyên Không Chiều Không Gian: Kích hoạt hiệu ứng này sau khi chơi thẻ lệnh lần đầu tiên mỗi vòng, tạm thời đặt Bản gốc của nó vào Khoảng không gian siêu việt, Vòng Siêu Chiều không thể kích hoạt hiệu ứng này.\n·Vòng Siêu Chiều: Sau khi vào Vòng Siêu Chiều, đặt tất cả thẻ bài trong Khoảng không gian siêu việt vào tay thay thế cho việc Rút bài. Sát thương, lá chắn, hồi phục Sinh lực, Năng lượng chìa khóa bạc, điên cuồng, thay đổi lực lượng, Ngộ độc, phản công, Chảy máu gây ra trong Vòng Siêu Chiều giảm 25%.\n·Sự diệt vong: Mỗi vòng 1 lần, có thể loại bỏ thẻ bài ngoài cùng bên trái trong Khoảng không gian siêu việt, đặt 1 thẻ \"Cảm hứng\" vào tay.\n·Siêu việt tinh thông: Cứ mỗi 1 điểm Sự thông thạo giới vực của đội, khi bắt đầu vòng có xác suất 0.125％ (<BlueQuality:[Arg1]%>) nhận được 1 thẻ \"Cảm hứng\", xác suất vượt quá 100% có thể nhận được nhiều thẻ.\n·Siêu việt: Nếu đội chỉ bao gồm thân thể siêu thức tỉnh, hiệu ứng thuộc tính Siêu việt tinh thông tăng gấp đôi và không còn bị ảnh hưởng bởi hiệu ứng giảm năng lực trong Vòng Siêu Chiều."
  },
  SchoolConfig_3_SchoolBattleTips_2 = {
    Text = "·Xuyên Không Chiều Không Gian: Kích hoạt hiệu ứng này sau khi chơi thẻ lệnh lần đầu tiên mỗi vòng, tạm thời đặt Bản gốc của nó vào Khoảng không gian siêu việt và trao cho nó cùng bản sao tạm thời <BlueQuality:[Arg2]> lớp \"Ngọn hải đăng kỳ điểm\", Vòng Siêu Chiều không thể kích hoạt hiệu ứng này.\n·Ngọn hải đăng kỳ điểm: Mỗi lớp sở hữu làm tăng 2% hiệu ứng cuối cùng của sát thương, lực lượng cố định và thương tổn xúc tu tăng, Ngộ độc cố định, phản công cố định mà thẻ bài này gây ra; tăng 1% hiệu ứng cuối cùng của lá chắn cố định, hồi phục Sinh lực cố định, sức mạnh giảm xuống, bị loại bỏ sau khi chơi. Thẻ bài sở hữu Ngọn hải đăng kỳ điểm không thể kích hoạt \"Xuyên Không Chiều Không Gian\".\n·Khoảng không gian siêu việt: Khi đạt đến giới hạn, cuối vòng thay vào đó kích hoạt Khoảng không gian siêu việt, không còn nhận được vòng bổ sung, bỏ các thẻ tay không được Giữ lại và kích hoạt hiệu ứng Hư vô, đặt tất cả thẻ bài trong Khoảng không gian siêu việt vào tay, đặt Điểm tính toán hiện tại thành 5 điểm. Sau khi kích hoạt Khoảng không gian siêu việt, vòng này được coi là Vòng Siêu Chiều.\n·Kỳ Điểm Sự diệt vong: Lấy thẻ bài ngoài cùng bên trái trong Khoảng không gian siêu việt, lần \"Biến dạng Kỳ Điểm\" tiếp theo trong vòng này có thể được kích hoạt. Hồi chiêu 3 vòng.\n·Sau khi bắt đầu khám phá, Khuếch đại sát thương của đội +50% và nhận được 15 lớp \"Lăng Kính Kỳ Điểm\".\n·\"Lăng Kính Kỳ Điểm\": Tất cả thẻ lệnh được coi là có phần thưởng Ngọn hải đăng kỳ điểm tương đương.\n·Siêu việt tinh thông: Cứ mỗi 1 điểm Sự thông thạo giới vực của đội, làm tăng 0.05% số lớp \"Ngọn hải đăng kỳ điểm\" mà \"Lăng Kính Kỳ Điểm\" và \"Xuyên Không Chiều Không Gian\" áp dụng.\n·Siêu việt: Nếu đội chỉ bao gồm thân thể siêu thức tỉnh hoặc thân thể hỗn độn, hiệu ứng Siêu việt tinh thông và Khuếch đại sát thương do Cõi cung cấp tăng gấp đôi."
